interface 是一个方法集合，任何实现了这些方法的类型都满足该接口。type Speaker interface {
    Speak() string
}
type Dog struct {
    Name string
}
func (d Dog) Speak() string {
    return "汪汪！"
}
func (d Dog) Run() {
    fmt.Println("狗跑起来了")
}
// 函数参数是接口
func MakeSpeak(s Speaker) {
    fmt.Println(s.Speak())
}


func main() {
    var s1 Speaker = Dog{Name: "旺财"}  // s1 是 Speaker 接口类型
    s2 := Dog{Name: "大福"}              // s2 是 Dog 结构体类型

    // ========== 传入 MakeSpeak ==========
    MakeSpeak(s1)               // ✅ s1 是 Speaker 接口，直接传入
    MakeSpeak(s2)               // ✅ s2 是 Dog 类型，Go 自动转成 Speaker（因为实现了 Speak()）
    MakeSpeak(Dog{Name: "阿黄"}) // ✅ 字面量 Dog 类型，自动转成 Speaker

    // ========== s1（接口类型）的方法调用 ==========
    s1.Speak() // ✅ 能调用，Speaker 接口有 Speak() 方法
    // s1.Run() // ❌ 编译错误！Speaker 接口没有 Run() 方法

    // ========== s2（具体类型）的方法调用 ==========
    s2.Speak() // ✅ 能调用，Dog 类型有 Speak() 方法
    s2.Run()   // ✅ 能调用，Dog 类型有 Run() 方法
}

