1. 实现多态让不同类型通过同一个接口被统一使用。type Speaker interface {
    Speak() string
}

type Dog struct{}
func (Dog) Speak() string { return "汪汪" }

type Cat struct{}
func (Cat) Speak() string { return "喵喵" }

func say(s Speaker) {
    fmt.Println(s.Speak())
}Dog 和 Cat 都能传给 say，调用者只关心接口行为，不关心具体类型。2. 解耦模块和依赖注入函数依赖接口，而不是依赖具体实现，方便替换实现。// 1. 定义接口（合同）
type Storage interface {
    Save(string) error
}

// 2. 实现1：文件存储
type FileStorage struct{}

func (f FileStorage) Save(data string) error {
    fmt.Println("保存到文件:", data)
    return nil
}

// 3. 实现2：数据库存储
type DBStorage struct{}

func (d DBStorage) Save(data string) error {
    fmt.Println("保存到数据库:", data)
    return nil
}

// 4. 业务函数只依赖接口
func Process(s Storage) error {
    return s.Save("data")
}

// 5. 使用时随便换
func main() {
    Process(FileStorage{})   // 用文件
    Process(DBStorage{})     // 换数据库，代码不用改
    Process(NetworkStorage{}) // 换成网络存储，也不用改
}Storage 可以由文件存储、数据库存储或网络存储实现，业务代码不需要修改。3. 模拟对象和测试测试时可以传入一个简单的假的接口实现，避免依赖真实数据库、网络等外部资源。type FakeStorage struct{}

func (FakeStorage) Save(string) error {
    return nil
}

func TestProcess() {
    err := Process(FakeStorage{})
    if err != nil {
        // 测试失败
    }
}

1. JSON/XML 序列化框架标准库 encoding/json 内部大量使用反射，根据运行时类型读取字段和 json 标签：type User struct {
    Name string `json:"name"`
    Age  int    `json:"age"`
}

data, _ := json.Marshal(User{Name: "Tom", Age: 18})
fmt.Println(string(data)) // {"name":"Tom","age":18}// encoding/json 内部伪代码
func Marshal(v interface{}) ([]byte, error) {
	rv := reflect.ValueOf(v)      // 1. 获取反射值
	rt := rv.Type()               // 2. 获取反射类型

	if rt.Kind() != reflect.Struct {
		// 处理非结构体...
	}

	var result string
	result += "{"

	for i := 0; i < rv.NumField(); i++ {
		field := rv.Field(i)                // 3. 获取字段值
		tag := rt.Field(i).Tag.Get("json")  // 4. 读取 json tag

		// 5. 根据 tag 决定字段名
		fieldName := getJSONName(tag, rt.Field(i).Name)

		// 6. 根据字段类型转成 JSON 字符串
		value := convertToJSON(field)

		result += fieldName + ":" + value
	}

