两种解决思路:


第一种,判断的时候使用反射判断nil,不要直接!=或者==,而是使用isNil里的方法

import "reflect"


func IsNil(i interface{}) bool {
    // 第一步：先判断是否为空接口
    if i == nil {
        return true
    }

    // 第二步：获取反射值对象
    v := reflect.ValueOf(i)

    // 第三步：判断底层类型是否可能为 nil
    switch v.Kind() {
    case reflect.Ptr, reflect.Slice, reflect.Map, 
         reflect.Chan, reflect.Func, reflect.Interface:
        return v.IsNil()  // ← 核心！用反射的 IsNil() 方法
    default:
        return false      // 其他类型不可能为 nil
    }
}


第二种,别把具体类型的 nil 赋值给接口后再判空
// ❌ 错误写法
func test() error {
    var e *MyError = nil
    return e
}
// ✅ 正确写法
func test() error {
    return nil
}

